if (existsSync(logPath)) {
  const raw = readFileSync(logPath);
  let start = 0;
  const lines = [];
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] === 0x0a) {
      const line = raw.toString('utf8', start, i);
      start = i + 1;
      if (line.length > 0) lines.push(line);
    }
  }
  const tornTail = start < raw.length;

